% hjfy: prepare_unicode -- Unicode typesetting for the translation
\usepackage[UTF8,fontset=fandol,heading=false,scheme=plain]{ctex}
% hjfy: prefer the complete installed Noto CJK family for automatic CJK setup.
% Never download fonts during compilation; keep CTeX's Fandol fallback if absent.
\IfFontExistsTF{NotoSerifCJKsc-Regular.otf}{%
  \IfFontExistsTF{NotoSerifCJKsc-Bold.otf}{%
    \IfFontExistsTF{NotoSansCJKsc-Regular.otf}{%
      \IfFontExistsTF{NotoSansCJKsc-Bold.otf}{%
        \setCJKmainfont[BoldFont=NotoSerifCJKsc-Bold.otf,
          ItalicFont=NotoSerifCJKsc-Regular.otf,ItalicFeatures={FakeSlant=0.2},
          BoldItalicFont=NotoSerifCJKsc-Bold.otf,BoldItalicFeatures={FakeSlant=0.2}]{NotoSerifCJKsc-Regular.otf}%
        \setCJKsansfont[BoldFont=NotoSansCJKsc-Bold.otf]{NotoSansCJKsc-Regular.otf}%
        \setCJKmonofont[BoldFont=NotoSansCJKsc-Bold.otf]{NotoSansCJKsc-Regular.otf}%
        \typeout{hjfy: automatic CJK fonts: Noto CJK SC}%
      }{\typeout{hjfy: Noto CJK incomplete; retaining Fandol}}%
    }{\typeout{hjfy: Noto CJK incomplete; retaining Fandol}}%
  }{\typeout{hjfy: Noto CJK incomplete; retaining Fandol}}%
}{\typeout{hjfy: Noto CJK unavailable; retaining Fandol}}
\usepackage[UTF8,fontset=none,heading=false,scheme=plain]{ctex}
\setCJKmainfont[BoldFont=FandolSong-Bold.otf,ItalicFont=FandolKai-Regular.otf]{FandolSong-Regular.otf}
\setCJKsansfont[BoldFont=FandolHei-Bold.otf]{FandolHei-Regular.otf}
\setCJKmonofont{FandolFang-Regular.otf}
